// CC0 low-poly models (Kenney kits in public/models, catalog in catalog.json generated by shorts/catalog.py),
// toon-shaded so the ink pass and the grade treat them like the rest of the world. Loaded on demand, cloned per prop.
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { clone as cloneSkinned } from "three/examples/jsm/utils/SkeletonUtils.js";
import { staticFile } from "remotion";
import catalogJson from "./catalog.json";

type Entry = { file: string; scale: number; h: number };
export const CATALOG = catalogJson as Record<string, Entry>;

let gradient: THREE.DataTexture | null = null;
export const toonGradient = () => {
  if (gradient) return gradient;
  const d = new Uint8Array([120, 120, 120, 255, 205, 205, 205, 255, 255, 255, 255, 255]);
  gradient = new THREE.DataTexture(d, 3, 1, THREE.RGBAFormat);
  gradient.minFilter = gradient.magFilter = THREE.NearestFilter;
  gradient.needsUpdate = true;
  return gradient;
};

const mats = new Map<string, THREE.Material>();
export const toon = (color: string) => {
  let m = mats.get(color);
  if (!m) mats.set(color, (m = new THREE.MeshToonMaterial({ color, gradientMap: toonGradient() })));
  return m;
};

/** the nature kit ships teal leaves and pastel rocks: map its material names to natural colours */
const RECOLOR: Record<string, string> = {
  grass: "#6fae45", dirt: "#9c7350", dirtDark: "#7a573c", stone: "#9d9890", stoneDark: "#7e7a75",
  leafsDark: "#3f7a3a", leafsGreen: "#5f9e3c", leafsFall: "#d9822b", water: "#4f8fc0",
  woodBark: "#7a5235", woodBarkDark: "#5e3f2a", wood: "#a5754a", woodDark: "#6b4a33", woodBirch: "#e8e1cf", woodInner: "#d9b98f",
};

const toonify = (src: THREE.Object3D) => {
  const cache = new Map<THREE.Material, THREE.Material>();
  src.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const conv = (mat: THREE.Material) => {
      let t = cache.get(mat);
      if (!t) {
        const s = mat as THREE.MeshStandardMaterial;
        const fixed = RECOLOR[s.name];
        const color = fixed ? new THREE.Color(fixed) : s.color?.clone() ?? new THREE.Color("#ffffff");
        t = new THREE.MeshToonMaterial({ color, map: s.map ?? null, gradientMap: toonGradient() });
        cache.set(mat, t);
      }
      return t;
    };
    m.material = Array.isArray(m.material) ? m.material.map(conv) : conv(m.material);
    m.castShadow = m.receiveShadow = true;
  });
};

/** template: base on the ground, centred, scaled from model units to metres */
const prepare = (src: THREE.Object3D, scale: number) => {
  toonify(src);
  const box = new THREE.Box3().setFromObject(src);
  const centre = box.getCenter(new THREE.Vector3());
  src.position.set(-centre.x, -box.min.y, -centre.z);
  const g = new THREE.Group();
  g.add(src);
  g.scale.setScalar(scale);
  return g;
};

const templates = new Map<string, THREE.Object3D>();
const pending = new Map<string, Promise<void>>();
const loader = new GLTFLoader();

/** load the given catalog keys (and the 3D animals) once; later calls reuse the cache */
export const loadModels = (keys: string[]) =>
  Promise.all([
    loadAnimals(),
    ...keys.filter((k) => CATALOG[k]).map((k) => {
      let p = pending.get(k);
      if (!p) {
        const e = CATALOG[k];
        p = loader.loadAsync(staticFile(e.file)).then(
          (gltf) => { templates.set(k, prepare(gltf.scene, e.scale)); },
          (err) => { console.warn("model failed", k, err); },
        );
        pending.set(k, p);
      }
      return p;
    }),
  ]).then(() => undefined);

/** a fresh copy of a catalog model, or null if it is unknown / failed to load */
export const modelFor = (key: string): THREE.Group | null => {
  const t = templates.get(key);
  return t ? (t.clone(true) as THREE.Group) : null;
};

// ---------------- animated 3D animals ----------------

type AnimalEntry = { file: string; h: number; clips: { idle: string; walk: string; run: string; jump?: string; death?: string }; yaw?: number; tint?: string };
/** species -> animated model (filled from the CC0 Quaternius packs in public/models/animals) */
const A = (name: string, h: number, clips: AnimalEntry["clips"], tint?: string, yaw = 0): AnimalEntry => ({ file: `models/animals/${name}.glb`, h, clips, tint, yaw });
const FULL = { idle: "Idle", walk: "|Walk", run: "Run", jump: "Jump", death: "Death" };
const WALKER = { idle: "Idle", walk: "Walking", run: "Walking" };
const SWIM = { idle: "Swim", walk: "Swim", run: "Swim" };
const HOPPER = { idle: "Idle", walk: "Jump", run: "Jump", jump: "Jump" };
export const ANIMALS3D: Record<string, AnimalEntry> = {
  cow: A("cow", 1.5, FULL), horse: A("horse", 1.8, FULL), zebra: A("zebra", 1.5, FULL),
  // the Vol.2 animals (dog, cat, wolf, eagle, piranha) are modelled facing the other way
  dog: A("dog", 0.7, WALKER, "#b5824f", Math.PI), cat: A("cat", 0.45, WALKER, undefined, Math.PI), wolf: A("wolf", 0.85, WALKER, "#7f838d", Math.PI),
  pig: A("pig", 0.85, HOPPER), sheep: A("sheep", 0.9, HOPPER), llama: A("llama", 1.8, HOPPER), pug: A("pug", 0.45, HOPPER),
  eagle: A("eagle", 0.9, { idle: "Idle", walk: "Flying", run: "Flying", jump: "Flying" }, undefined, Math.PI),
  fish: A("piranha", 0.4, { idle: "Swimming", walk: "Swimming", run: "Swimming", jump: "Bite" }, undefined, Math.PI),
  // Quaternius animated fish pack: one swim cycle each
  whale: A("whale", 3.2, SWIM), shark: A("shark", 1.0, SWIM), dolphin: A("dolphin", 0.8, SWIM), manta: A("manta_ray", 0.5, SWIM),
};

type AnimalTemplate = { scene: THREE.Object3D; clips: THREE.AnimationClip[]; entry: AnimalEntry; scale: number; lift: number; cx: number; cz: number };
const animalTemplates = new Map<string, AnimalTemplate>();

let animalsLoading: Promise<void> | null = null;
export const loadAnimals = () => {
  if (animalsLoading) return animalsLoading;
  return (animalsLoading = Promise.all(Object.entries(ANIMALS3D).map(([species, e]) =>
    loader.loadAsync(staticFile(e.file)).then((gltf) => {
      const box = new THREE.Box3().setFromObject(gltf.scene);
      const size = box.getSize(new THREE.Vector3());
      const c = box.getCenter(new THREE.Vector3());
      animalTemplates.set(species, { scene: gltf.scene, clips: gltf.animations, entry: e, scale: e.h / Math.max(1e-3, size.y), lift: -box.min.y, cx: c.x, cz: c.z });
    }, (err) => console.warn("animal failed", species, err)),
  )).then(() => undefined));
};

export const hasAnimal3D = (species: string) => animalTemplates.has(species);

export class AnimalModel {
  readonly root = new THREE.Group();
  private mixer: THREE.AnimationMixer;
  private actions = new Map<string, THREE.AnimationAction>();
  private tpl: AnimalTemplate;
  private current = "";
  /** set by the world when this animal is the subject of a close/medium shot: turn it 3/4 toward the lens */
  closeUp = false;

  constructor(species: string, contact: THREE.Texture) {
    this.tpl = animalTemplates.get(species)!;
    const obj = cloneSkinned(this.tpl.scene);
    const toonCache = new Map<THREE.Material, THREE.Material>();
    obj.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const conv = (mat: THREE.Material) => {
        let t = toonCache.get(mat);
        if (!t) {
          const s = mat as THREE.MeshStandardMaterial;
          const vc = !!(m.geometry as THREE.BufferGeometry).attributes.color;
          const color = this.tpl.entry.tint ? new THREE.Color(this.tpl.entry.tint) : s.color?.clone() ?? new THREE.Color("#ffffff");
          t = new THREE.MeshToonMaterial({ color, map: s.map ?? null, vertexColors: vc, gradientMap: toonGradient() });
          toonCache.set(mat, t);
        }
        return t;
      };
      m.material = Array.isArray(m.material) ? m.material.map(conv) : conv(m.material);
      m.castShadow = true;
      m.frustumCulled = false;
    });
    obj.scale.setScalar(this.tpl.scale);
    obj.position.set(-this.tpl.cx * this.tpl.scale, this.tpl.lift * this.tpl.scale, -this.tpl.cz * this.tpl.scale);
    const turn = new THREE.Group();
    turn.add(obj);
    this.root.add(turn);
    const w = this.tpl.entry.h * 1.1;
    const blob = new THREE.Mesh(new THREE.PlaneGeometry(w * 1.4, w * 0.7),
      new THREE.MeshBasicMaterial({ map: contact, transparent: true, depthWrite: false, fog: false }));
    blob.rotation.x = -Math.PI / 2;
    blob.position.y = 0.02;
    this.root.add(blob);
    this.mixer = new THREE.AnimationMixer(obj);
    for (const c of this.tpl.clips) this.actions.set(c.name, this.mixer.clipAction(c));
  }

  private clip(name: string | undefined) {
    if (!name) return undefined;
    return this.actions.get(name) ?? [...this.actions.entries()].find(([k]) => k.toLowerCase().includes(name.toLowerCase()))?.[1];
  }

  update(p: { x: number; y: number; z: number; side: boolean; flip: boolean; mode: string; stride: number }, camera: THREE.Camera, t: number) {
    this.root.position.set(p.x, p.y, p.z);
    const turn = this.root.children[0];
    const yaw = this.tpl.entry.yaw ?? 0;
    // walking: profile toward the direction of travel; otherwise a 3/4 view toward the camera
    turn.rotation.y = p.side
      ? yaw + (p.flip ? -Math.PI / 2 : Math.PI / 2)
      : yaw + Math.atan2(camera.position.x - p.x, camera.position.z - p.z) + (p.x > 0 ? -1 : 1) * (this.closeUp ? 0.55 : 1.15);
    const c = this.tpl.entry.clips;
    const want = p.mode === "fall" ? c.death ?? c.idle : p.side ? (p.stride > 1.2 ? c.run : c.walk) : p.y > 0.05 ? c.jump ?? c.idle : c.idle;
    const action = this.clip(want) ?? this.clip(c.idle);
    if (!action) return;
    if (this.current !== want) {
      this.mixer.stopAllAction();
      action.reset().play();
      if (p.mode === "fall") { action.setLoop(THREE.LoopOnce, 1); action.clampWhenFinished = true; }
      this.current = want;
    }
    // deterministic: the pose depends only on the frame
    const d = action.getClip().duration || 1;
    action.time = p.mode === "fall" ? Math.min(d - 0.01, t / 30) : (t / 30) % d;
    this.mixer.update(0);
  }
}
